using System.Data;using Essco.Application.Inventory;using Microsoft.Data.SqlClient;namespace Essco.Infrastructure.Data;
public sealed class SqlServerInventoryCreationRepository(string connectionString,int timeout):IInventoryCreationRepository
{public async ValueTask<InventoryCreationResult>CreateAsync(string title,string comments,CancellationToken token){await using var c=new SqlConnection(connectionString);await c.OpenAsync(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable,token);try{await using(var check=Cmd("SELECT COUNT(*) FROM [dbo].[Inv_Registro] WITH (UPDLOCK,HOLDLOCK) WHERE ISNULL([Cerrado],0)=0",c,tx)){if(Convert.ToInt32(await check.ExecuteScalarAsync(token))>0){await tx.RollbackAsync(token);return new(false,Error:"Existe un inventario abierto.");}}int id;await using(var head=Cmd("INSERT INTO [dbo].[Inv_Registro]([Fecha],[Titulo],[Comentario],[Cerrado],[InvInicial],[InvFinal],[ENTRADAS],[SALIDAS],[DIFERENCIAS]) OUTPUT INSERTED.[id] VALUES(CAST(SYSDATETIME() AS date),@Title,@Comments,0,0,0,0,0,0)",c,tx)){P(head,"@Title",300,title);P(head,"@Comments",1000,comments);id=Convert.ToInt32(await head.ExecuteScalarAsync(token));}const string copy="INSERT INTO [dbo].[Inv_Inventario]([Fecha],[IdInventario],[Codigo],[Descripcion],[CodBarras],[Sector],[Costo],[CodProveedor],[NameProveedor],[Stock],[Monto],[Reconteo],[CF],[DF],[DFM],[Pack],[NumLinea]) SELECT CAST(SYSDATETIME() AS date),@Id,[ItemCode],[ItemName],ISNULL([CodeBars],''),ISNULL(TRY_CONVERT(int,[Sector]),0),ISNULL(TRY_CONVERT(decimal(19,4),[Price]),0),ISNULL([CodProveedor],''),ISNULL([NameProveedor],''),ISNULL(TRY_CONVERT(decimal(19,4),[Stock_B1]),0),ISNULL(TRY_CONVERT(decimal(19,4),[Monto_B1]),0),0,0,-ISNULL(TRY_CONVERT(decimal(19,4),[Stock_B1]),0),-ISNULL(TRY_CONVERT(decimal(19,4),[Monto_B1]),0),ISNULL(TRY_CONVERT(decimal(19,4),[Empaque]),0),ROW_NUMBER() OVER(ORDER BY [ItemCode])-1 FROM [dbo].[Inve_Conteo]";int lines;await using(var insert=Cmd(copy,c,tx)){insert.Parameters.Add("@Id",SqlDbType.Int).Value=id;lines=await insert.ExecuteNonQueryAsync(token);}if(lines==0){await tx.RollbackAsync(token);return new(false,Error:"El universo Inve_Conteo está vacío.");}await using(var total=Cmd("UPDATE R SET [InvInicial]=X.Total FROM [dbo].[Inv_Registro] R CROSS APPLY(SELECT ISNULL(SUM([Monto]),0) Total FROM [dbo].[Inv_Inventario] WHERE [IdInventario]=@Id) X WHERE R.[id]=@Id",c,tx)){total.Parameters.Add("@Id",SqlDbType.Int).Value=id;await total.ExecuteNonQueryAsync(token);}await tx.CommitAsync(token);return new(true,id);}catch{await tx.RollbackAsync(token);throw;}}private SqlCommand Cmd(string s,SqlConnection c,SqlTransaction t)=>new(s,c,t){CommandTimeout=timeout};private static void P(SqlCommand c,string n,int z,string v)=>c.Parameters.Add(n,SqlDbType.NVarChar,z).Value=v;}
